using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static int CountAsync(IEnumerable<int> values, CancellationToken token)
    {
        int count = 0;
        foreach (int value in values)
        {
            if (value > 0)
            {
                count += 1;
            }
        }
        return Task.FromResult(count).Result; // TODO: await and honor cancellation
    }

    static void Main()
    {
        Console.WriteLine(CountAsync(new[] { 3, -1, 2 }, CancellationToken.None));
    }
}
